pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;
    function setUp() public { c = new airdrop(); }
    function testFuzz_property(address from, address to, uint256 v) public {
        vm.assume(to != address(0));
        vm.assume(caddress_ok(from, to));
        address[] memory tos = new address[](1);
        tos[0] = to;
        // low-level call to an EOA (no code) succeeds, so the loop's require passes
        assertTrue(c.transfer(from, address(0), tos, v), "transfer must return true on success");
    }
    function caddress_ok(address from, address to) internal pure returns (bool) {
        return from != address(0) || to != address(0);
    }
}
